library(clusterProfiler); library(org.Hs.eg.db); library(AnnotationDbi)
out<-normalizePath("outputs",mustWork=TRUE);tt<-read.csv(file.path(out,"limma_GSE32537_IPF_UIP_vs_control_adjusted.csv"));
tt$entrez<-mapIds(org.Hs.eg.db,keys=tt$gene,column="ENTREZID",keytype="SYMBOL",multiVals="first"); bg<-na.omit(unique(tt$entrez));
run<-function(direction){x<-tt[tt$adj.P.Val<0.05 & sign(tt$logFC)==direction,]; g<-na.omit(unique(x$entrez)); if(length(g)<5)return(NULL); enrichGO(gene=g,universe=bg,OrgDb=org.Hs.eg.db,keyType="ENTREZID",ont="BP",pAdjustMethod="BH",readable=TRUE)}
up<-run(1);down<-run(-1); if(!is.null(up))write.csv(as.data.frame(up),file.path(out,"GO_ORA_up_GSE32537.csv"),row.names=FALSE,fileEncoding="UTF-8");if(!is.null(down))write.csv(as.data.frame(down),file.path(out,"GO_ORA_down_GSE32537.csv"),row.names=FALSE,fileEncoding="UTF-8");capture.output({cat("GO ORA from adjusted limma results; universe=all tested and mappable genes.\n");cat("Up genes:",sum(tt$adj.P.Val<0.05&tt$logFC>0,na.rm=TRUE)," Down genes:",sum(tt$adj.P.Val<0.05&tt$logFC<0,na.rm=TRUE)," Background:",length(bg),"\n\nUP:\n");if(!is.null(up))print(head(as.data.frame(up),20));cat("\nDOWN:\n");if(!is.null(down))print(head(as.data.frame(down),20))},file=file.path(out,"GO_ORA_report.txt"))
